setBaseUrl('');

const queryClient = new QueryClient();
const money = (value: number) => `₹${Number(value || 0).toLocaleString('en-IN', { maximumFractionDigits: 0 })}`;
const dateLabel = (date?: string) => date ? new Date(date).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' }) : '—';
const sessionKey = 'farmdirect-session';
const cartKey = 'farmdirect-cart';

function getSession(): User | null {
  try { return JSON.parse(localStorage.getItem(sessionKey) || 'null')?.user || null; } catch { return null; }
}
function initials(name = 'FarmDirect') {
  return name.split(' ').map((part) => part[0]).slice(0, 2).join('').toUpperCase();
}

function Logo({ inverse = false }: { inverse?: boolean }) {
  return <Link href="/" data-testid="link-logo" className="flex items-center gap-2.5">
    <span className={`flex h-9 w-9 items-center justify-center rounded-xl ${inverse ? 'bg-[hsl(var(--accent))] text-[hsl(var(--primary))]' : 'bg-[hsl(var(--primary))] text-[hsl(var(--accent))]'}`}><Sprout size={19} strokeWidth={2.5} /></span>
    <span className={`text-lg font-extrabold tracking-[-.04em] ${inverse ? 'text-[hsl(var(--sidebar-foreground))]' : 'text-[hsl(var(--foreground))]'}`}>farm<span className="text-[hsl(var(--accent))]">direct</span></span>
  </Link>;
}

const calculateDeliveryFee = (subtotal: number): number => {
  if (!subtotal || subtotal <= 0) return 0;
  if (subtotal >= 250) return 0;
  if (subtotal < 50) return 10;
  if (subtotal < 150) return 15;
  return 20;
};

function Button({ children, variant = 'primary', className = '', ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'soft' | 'ghost' | 'danger' }) {
  const styles = {
    primary: 'bg-[hsl(var(--primary))] text-white hover:bg-[#1e4837] active:scale-[0.99] shadow-md font-extrabold cursor-pointer border border-transparent',
    soft: 'bg-[hsl(var(--secondary))] text-[hsl(var(--primary))] hover:bg-[hsl(var(--accent))] hover:text-[hsl(var(--accent-foreground))] font-extrabold cursor-pointer border border-[hsl(var(--border))]',
    ghost: 'text-[hsl(var(--foreground))] hover:bg-[hsl(var(--muted))] font-bold cursor-pointer',
    danger: 'bg-[hsl(var(--destructive))] text-white hover:brightness-110 font-extrabold cursor-pointer',
  };
  return <button {...props} className={`inline-flex items-center justify-center gap-2 rounded-xl px-5 py-3 text-sm font-extrabold transition-all disabled:cursor-not-allowed disabled:opacity-50 ${styles[variant]} ${className}`}>{children}</button>;
}

function Badge({ children, tone = 'default' }: { children: React.ReactNode; tone?: 'default' | 'green' | 'yellow' | 'red' | 'blue' }) {
  const tones = { default: 'bg-[hsl(var(--muted))] text-[hsl(var(--muted-foreground))]', green: 'bg-[#dceee3] text-[#23613f]', yellow: 'bg-[#f9e9ac] text-[#70570c]', red: 'bg-[#f5d8d2] text-[#934438]', blue: 'bg-[#dce9ef] text-[#285c70]' };
  return <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-extrabold uppercase tracking-[.08em] ${tones[tone]}`}>{children}</span>;
}

function ProductVisual({ product, large = false }: { product: Product; large?: boolean }) {
  const color = product.category?.toLowerCase().includes('fruit') ? 'from-[#efc788] to-[#da9562]' : product.category?.toLowerCase().includes('grain') ? 'from-[#d8ca8b] to-[#b3a060]' : 'from-[#a7c8a5] to-[#5d9a75]';
  return <div className={`relative overflow-hidden bg-gradient-to-br ${color} ${large ? 'h-80 md:h-[28rem]' : 'h-44'} flex items-end`}>
    {product.image ? <img src={product.image} alt={product.name} className="absolute inset-0 h-full w-full object-cover mix-blend-multiply opacity-75" /> : null}
    <div className="absolute -right-7 -top-8 h-32 w-32 rounded-full border-[18px] border-white/20" />
    <div className="absolute -bottom-12 -left-8 h-40 w-40 rounded-full border-[22px] border-black/10" />
    <div className="relative w-full bg-gradient-to-t from-black/40 to-transparent p-4 pt-12 text-white">
      <span className="text-[10px] font-extrabold uppercase tracking-[.14em]">{product.category || 'Harvest'}</span>
    </div>
  </div>;
}

function LoadingState({ label = 'Gathering the latest market details' }: { label?: string }) {
  return <div className="space-y-4" data-testid="state-loading"><div className="fd-skeleton h-28 rounded-2xl" /><div className="grid gap-4 md:grid-cols-3"><div className="fd-skeleton h-52 rounded-2xl" /><div className="fd-skeleton h-52 rounded-2xl" /><div className="fd-skeleton h-52 rounded-2xl" /></div><p className="fd-mono text-center text-[11px] text-[hsl(var(--muted-foreground))]">{label}</p></div>;
}
function ErrorState({ retry }: { retry?: () => void }) {
  return <div className="fd-card flex flex-col items-center justify-center gap-3 p-12 text-center" data-testid="state-error"><CircleAlert className="text-[hsl(var(--destructive))]" /><h3 className="font-bold">The market board is taking a breather</h3><p className="max-w-sm text-sm text-[hsl(var(--muted-foreground))]">We couldn’t load this view just now. Your place in the market is safe.</p>{retry && <Button onClick={retry} data-testid="button-retry">Try again</Button>}</div>;
}
function EmptyState({ title, copy, action }: { title: string; copy: string; action?: React.ReactNode }) {
  return <div className="fd-card flex flex-col items-center justify-center gap-3 p-12 text-center" data-testid="state-empty"><span className="flex h-14 w-14 items-center justify-center rounded-2xl bg-[hsl(var(--secondary))] text-[hsl(var(--primary))]"><Leaf /></span><h3 className="font-bold">{title}</h3><p className="max-w-sm text-sm text-[hsl(var(--muted-foreground))]">{copy}</p>{action}</div>;
}

